new_imp = '''import { Nav, Popover } from "@foldkit/ui";
import { Option, Predicate, Schema } from "effect";
import type { ChildAttribute, Html, HtmlBuilder } from "foldkit/html";
import { defineTaggedUnion } from "foldkit/schema";
import { formatDate, message } from "../messages/locale.ts";
import { Failure } from "./api.ts";
import {
  type Child,
  appButton,
  badge,
  dataTable,
  emptyState,
  linkButton,
  linkClass,
  pageShell,
  pageTitle,
  problemView,
  selectField,
  signOutView,
  checkboxField,
  subSectionTitle,
  textField,
} from "./components.ts";
import { historyHref, pulsesHref, settingsHref, teamHref, teamsHref } from "./routes.ts";
import { failureReasonText } from "./pulses.ts";

'''
