57	      const screen = detail !== undefined ? detail.settings.name : message("title.pulse");
58	      const context = teamContext(route.teamId, [detail?.team, detailTeam(source.teamDetail)], organization);
59	      return documentTitle(screen, context);
60	    }
61	    case "Rounds":
62	      return documentTitle(
63	        message("rounds.title"),
64	        teamContext(route.teamId, [detailTeam(source.teamDetail)], organization),
65	      );
66	    case "RoundResults":
67	      return documentTitle(
