// Local browser check of the header, account and phone menus, footer, titles and overflow (mocked API).
const http = require("node:http");
const fs = require("node:fs");
const path = require("node:path");
const { createRequire } = require("node:module");
const infraRequire = createRequire("/home/ubuntu/.t3/worktrees/surveybeat-next/t3-8f70e25d-9104a747308defc5/infra/package.json");
const { chromium } = infraRequire("@playwright/test");

const dist = "/home/ubuntu/.t3/worktrees/surveybeat-next/t3-8f70e25d-9104a747308defc5/apps/web/dist";
const scratch = process.argv[2];
const port = 4199;
const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://x");
  let file = path.join(dist, url.pathname);
  if (fs.existsSync(file) && fs.statSync(file).isDirectory()) file = path.join(file, "index.html");
  if (!fs.existsSync(file) || url.pathname === "/") file = path.join(dist, "index.html");
  const type = file.endsWith(".js") ? "text/javascript" : file.endsWith(".css") ? "text/css" : file.endsWith(".html") ? "text/html" : "application/octet-stream";
  res.writeHead(200, { "content-type": type });
  fs.createReadStream(file).pipe(res);
});

const session = { _tag: "SignedIn", organization: { id: "org-1", name: "Acme Corporation Holdings International" }, personId: "person-1", organizationAdmin: true, locale: null, detectedLocale: null, organizationLocale: "en" };
const teams = [{ id: "team-1", name: "Platform Engineering", timeZone: "UTC", yourRole: "lead" }];

(async () => {
  await new Promise((r) => server.listen(port, r));
  const browser = await chromium.launch();
  const report = {};
  try {
    // Signed-out at 390 px: sign-in and Privacy.
    for (const width of [390, 1280]) {
      const page = await browser.newPage({ viewport: { width, height: 844 } });
      await page.route("**/api/**", (route) => route.fulfill({ status: 401, contentType: "application/json", body: JSON.stringify({ _tag: "Unauthenticated" }) }));
      for (const p of ["/", "/privacy"]) {
        await page.goto(`http://localhost:${port}${p}`);
        await page.waitForLoadState("networkidle");
        const footerLink = await page.getByRole("contentinfo").getByRole("link", { name: "Privacy" }).isVisible();
        const sw = await page.evaluate("document.documentElement.scrollWidth");
        report[`signedOut ${width} ${p}`] = { footerLink, scrollWidth: sw, title: await page.title() };
        await page.screenshot({ path: `${scratch}/signedout-${width}-${p.replace("/", "") || "root"}.png`, fullPage: true });
      }
      await page.close();
    }

    // Signed in as an admin, phone width.
    const phone = await browser.newPage({ viewport: { width: 390, height: 844 } });
    await phone.route("**/api/**", (route) => {
      const u = route.request().url();
      const body = u.endsWith("/session") ? session : u.endsWith("/teams") ? teams : [];
      return route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(body) });
    });
    await phone.goto(`http://localhost:${port}/teams`);
    await phone.getByRole("button", { name: "Menu" }).waitFor();
    const headerRow = await phone.locator("header > div").boundingBox();
    const menuBtn = await phone.getByRole("button", { name: "Menu" }).boundingBox();
    report.phoneHeader = { headerHeight: headerRow && headerRow.height, menuBox: menuBtn };
    report.phoneTitleClosed = await phone.title();
    await phone.getByRole("button", { name: "Menu" }).click();
